import struct
import sys

import wgpu

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
};

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let idx = gid.x;
    let total = p.width * p.height;
    if (idx >= total) {
        return;
    }
    let i = idx % p.width;
    let j = idx / p.width;
    let cx = p.x_min + (f32(i) + 0.5) * p.dx;
    let cy = p.y_min + (f32(j) + 0.5) * p.dy;
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= p.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[idx] = n;
}
"""


def escape_times(width, height, limit, x_min, x_max, y_min, y_max):
    device = wgpu.utils.get_default_device()
    total = width * height
    dx = (x_max - x_min) / width
    dy = (y_max - y_min) / height
    params = struct.pack("<4I4f", width, height, limit, 0, x_min, dx, y_min, dy)

    ubuf = device.create_buffer_with_data(data=params, usage=wgpu.BufferUsage.UNIFORM)
    obuf = device.create_buffer(
        size=total * 4,
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )
    rbuf = device.create_buffer(
        size=total * 4,
        usage=wgpu.BufferUsage.COPY_DST | wgpu.BufferUsage.MAP_READ,
    )
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": ubuf}},
            {"binding": 1, "resource": {"buffer": obuf}},
        ],
    )
    enc = device.create_command_encoder()
    cp = enc.begin_compute_pass()
    cp.set_pipeline(pipeline)
    cp.set_bind_group(0, bind)
    cp.dispatch_workgroups((total + 63) // 64)
    cp.end()
    enc.copy_buffer_to_buffer(obuf, 0, rbuf, 0, total * 4)
    device.queue.submit([enc.finish()])
    rbuf.map_sync(wgpu.MapMode.READ)
    data = bytes(rbuf.read_mapped())
    rbuf.unmap()
    return memoryview(data).cast("I")


def main():
    with open(sys.argv[1]) as f:
        tokens = f.read().split()
    width, height, limit = int(tokens[0]), int(tokens[1]), int(tokens[2])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])

    times = escape_times(width, height, limit, x_min, x_max, y_min, y_max)

    inside = 0
    bins = [0] * 8
    esc_sum = 0
    esc_count = 0
    for n in times:
        if n >= limit:
            inside += 1
        else:
            bins[min(7, 8 * n // limit)] += 1
            esc_sum += n
            esc_count += 1
    mean = esc_sum / esc_count if esc_count else 0.0

    out = [f"INSIDE {inside}"]
    out += [f"BIN {k} {c}" for k, c in enumerate(bins)]
    out.append(f"MEAN {mean:.3f}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
